"""Function library; no source-time data loading, downloads or analysis dispatch.
Private inputs and contexts must be provided explicitly.
"""
import argparse, hashlib, io, json, math
from pathlib import Path
import numpy as np
import pandas as pd
Z = 1.959963984540054

def save(df, path):
    assert not path.exists(), f'NO_OVERWRITE {path}'
    df.to_csv(path, index=False, float_format='%.16g')

def text(path, value):
    assert not path.exists(), f'NO_OVERWRITE {path}'
    with path.open('x') as f:
        f.write(value)

def p_chi(q, df):
    if df == 1:
        return math.erfc(math.sqrt(q / 2))
    if df == 2:
        return math.exp(-q / 2)
    if df == 3:
        return math.erfc(math.sqrt(q / 2)) + math.sqrt(2 * q / math.pi) * math.exp(-q / 2)
    raise ValueError(df)

def covariance(hr, se, n, cases, method):
    if method == 'GL_cumulative_working':
        pseudo0 = cases.sum() / np.sum(hr * n / n[0])
        a = pseudo0 * hr * n / n[0]
        assert np.all((a > 0) & (a < n)) and abs(a.sum() - cases.sum()) < 1e-07
        assert np.max(np.abs(a / n / (a[0] / n[0]) - hr)) < 1e-12
        q = 1 / a - 1 / n
    elif method == 'Raw_cumulative_correlation':
        a = cases.copy()
        q = 1 / a - 1 / n
    elif method == 'Raw_Poisson_case_correlation':
        a = cases.copy()
        q = 1 / a
    else:
        raise ValueError(method)
    v = q[0] + q[1:]
    rho = q[0] / np.sqrt(np.outer(v, v))
    np.fill_diagonal(rho, 1.0)
    C = np.outer(se[1:], se[1:]) * rho
    assert np.all(np.isfinite(C)) and np.linalg.eigvalsh(C).min() > 0
    assert np.max(abs(np.diag(C) - se[1:] ** 2)) < 1e-14
    return (C, rho, a)

def gls(y, x, C):
    ci_x = np.linalg.solve(C, x)
    variance = 1.0 / float(x @ ci_x)
    b = variance * float(ci_x @ y)
    se = math.sqrt(variance)
    res = y - x * b
    q = float(res @ np.linalg.solve(C, res))
    df = len(y) - 1
    return dict(beta=b, SE=se, estimate=math.exp(b), CI_lower=math.exp(b - Z * se), CI_upper=math.exp(b + Z * se), P=math.erfc(abs(b / se) / math.sqrt(2)), residual_Q=q, residual_df=df, residual_P=p_chi(q, df))

