    qc = dict(forest_rows=4, Sweden_user_approved_approximation=True, Sweden_actual_person_time_available=False, covariance_shared_reference=True, all_five_category_margins_retained=True, main_dose_ranks=[1, 2, 3, 4], covariance_sensitivities=methods, open_category_assigned_scores_sensitivity=[5, 6], UKB_additional_models=1, LASI_recomputed=False, cross_cohort_meta_performed=False, original_relative_B_modified=False)
