def run_in_private_context(context):
    if not isinstance(context, dict):
        raise TypeError('Explicit private stage namespace required')
    exec(compile('"""Approved exploratory GLST approximation, saved UKB/LASI reuse, no bulk fits."""\nimport argparse, hashlib, io, json, math\nfrom pathlib import Path\nimport numpy as np\nimport pandas as pd\nROOT = Path(__file__).resolve().parent\nPROJECT = ROOT.parents[2]\nREPORT = PROJECT / \'reports\' / ROOT.name\nZ = 1.959963984540054\n\ndef save(df, path):\n    assert not path.exists(), f\'NO_OVERWRITE {path}\'\n    df.to_csv(path, index=False, float_format=\'%.16g\')\n\ndef text(path, value):\n    assert not path.exists(), f\'NO_OVERWRITE {path}\'\n    with path.open(\'x\') as f:\n        f.write(value)\n\ndef p_chi(q, df):\n    if df == 1:\n        return math.erfc(math.sqrt(q / 2))\n    if df == 2:\n        return math.exp(-q / 2)\n    if df == 3:\n        return math.erfc(math.sqrt(q / 2)) + math.sqrt(2 * q / math.pi) * math.exp(-q / 2)\n    raise ValueError(df)\n\ndef covariance(hr, se, n, cases, method):\n    if method == \'GL_cumulative_working\':\n        pseudo0 = cases.sum() / np.sum(hr * n / n[0])\n        a = pseudo0 * hr * n / n[0]\n        assert np.all((a > 0) & (a < n)) and abs(a.sum() - cases.sum()) < 1e-07\n        assert np.max(np.abs(a / n / (a[0] / n[0]) - hr)) < 1e-12\n        q = 1 / a - 1 / n\n    elif method == \'Raw_cumulative_correlation\':\n        a = cases.copy()\n        q = 1 / a - 1 / n\n    elif method == \'Raw_Poisson_case_correlation\':\n        a = cases.copy()\n        q = 1 / a\n    else:\n        raise ValueError(method)\n    v = q[0] + q[1:]\n    rho = q[0] / np.sqrt(np.outer(v, v))\n    np.fill_diagonal(rho, 1.0)\n    C = np.outer(se[1:], se[1:]) * rho\n    assert np.all(np.isfinite(C)) and np.linalg.eigvalsh(C).min() > 0\n    assert np.max(abs(np.diag(C) - se[1:] ** 2)) < 1e-14\n    return (C, rho, a)\n\ndef gls(y, x, C):\n    ci_x = np.linalg.solve(C, x)\n    variance = 1.0 / float(x @ ci_x)\n    b = variance * float(ci_x @ y)\n    se = math.sqrt(variance)\n    res = y - x * b\n    q = float(res @ np.linalg.solve(C, res))\n    df = len(y) - 1\n    return dict(beta=b, SE=se, estimate=math.exp(b), CI_lower=math.exp(b - Z * se), CI_upper=math.exp(b + Z * se), P=math.erfc(abs(b / se) / math.sqrt(2)), residual_Q=q, residual_df=df, residual_P=p_chi(q, df))\n\ndef main():\n    assert REPORT.is_dir()\n    audit = REPORT / \'audit\'\n    audit.mkdir(exist_ok=True)\n    srcN = REPORT / \'literature_audit/sweden_table1_sex_rank_N_CHD_verified.tsv\'\n    srcHR = PROJECT / \'reports/birthorder_sweden_chd_external_20261104/01_SWEDEN_PUBLISHED_EFFECTS.csv\'\n    srcDM = PROJECT / \'reports/UKB_S8_relative_six_LASI_forest_20261030_v5/data/FOREST_EXACT_VALUES.csv\'\n    srcCox = REPORT / \'audit/ukb_trend/UKB_POOLED_RANK1_4_TREND.csv\'\n    assert json.loads((srcCox.parent / \'exit.json\').read_text())[\'exit_code\'] == 0\n    inp = []\n    for p in [srcN, srcHR, srcDM, srcCox]:\n        b = p.read_bytes()\n        inp.append(dict(path=str(p), bytes=len(b), sha256=hashlib.sha256(b).hexdigest()))\n    assert inp[2][\'sha256\'] == birth_private_setting(\'PRIVATE_5F5D35E7B61BDBE921E880EC0614243CCABE7C503CCBE7E10E344870CFFB\')\n    s = srcN.read_text()\n    s = s.replace(\'\\\\t\', \'\\t\') if \'\\\\t\' in s and \'\\t\' not in s else s\n    counts = pd.read_csv(io.StringIO(s), sep=\'\\t\', dtype={\'birth_rank\': str})\n    hr = pd.read_csv(srcHR, dtype={\'birth_rank\': str})\n    assert len(hr) == 8\n    rows = []\n    matrices = []\n    pseudo = []\n    methods = [\'GL_cumulative_working\', \'Raw_cumulative_correlation\', \'Raw_Poisson_case_correlation\']\n    scenarios = [(\'rank1_4\', None), (\'rank1_5plus_assigned5\', 5.0), (\'rank1_5plus_assigned6\', 6.0)]\n    for sex in [\'Male\', \'Female\']:\n        cc = counts[counts.sex == sex].set_index(\'birth_rank\').loc[[\'1\', \'2\', \'3\', \'4\', \'5+\']]\n        hh = hr[hr.sex == sex].set_index(\'birth_rank\').loc[[\'2\', \'3\', \'4\', \'5+\']]\n        h = np.r_[1.0, hh.HR.to_numpy()]\n        se = np.r_[0.0, (np.log(hh.UCI.to_numpy()) - np.log(hh.LCI.to_numpy())) / (2 * Z)]\n        n = cc.N.to_numpy(dtype=float)\n        cases = cc.CHD_cases.to_numpy(dtype=float)\n        assert np.all(cases < n) and n.sum() == {\'Male\': 1358647, \'Female\': 1315037}[sex]\n        for method in methods:\n            C, rho, a = covariance(h, se, n, cases, method)\n            for i, ranki in enumerate([\'2\', \'3\', \'4\', \'5+\']):\n                for j, rankj in enumerate([\'2\', \'3\', \'4\', \'5+\']):\n                    matrices.append(dict(sex=sex, covariance_method=method, rank_i=ranki, rank_j=rankj, covariance=C[i, j], correlation=rho[i, j]))\n            for rank, ni, ci, ai in zip([\'1\', \'2\', \'3\', \'4\', \'5+\'], n, cases, a):\n                pseudo.append(dict(sex=sex, covariance_method=method, birth_rank=rank, N=ni, published_CHD_cases=ci, working_cases=ai, person_years=\'NOT_REPORTED_NOT_IMPUTED\'))\n            for scenario, dose5 in scenarios:\n                ix = np.arange(3 if dose5 is None else 4)\n                x = np.array([1.0, 2.0, 3.0] if dose5 is None else [1.0, 2.0, 3.0, dose5 - 1])\n                r = gls(np.log(h[1:])[ix], x, C[np.ix_(ix, ix)])\n                rows.append(dict(sex=sex, scenario=scenario, covariance_method=method, N_source_model=int(n.sum()), N_in_rank1_4=int(n[:4].sum()), cases_source=int(cases.sum()), **r))\n    strata = pd.DataFrame(rows)\n    combined = []\n    for (scenario, method), g in strata.groupby([\'scenario\', \'covariance_method\'], sort=False):\n        assert set(g.sex) == {\'Male\', \'Female\'}\n        v = g.SE.to_numpy() ** 2\n        w = 1 / v\n        b = float(np.sum(w * g.beta) / w.sum())\n        se = float(1 / math.sqrt(w.sum()))\n        Q = float(np.sum(w * (g.beta - b) ** 2))\n        combined.append(dict(sex=\'Sex-combined\', scenario=scenario, covariance_method=method, N_source_model=int(g.N_source_model.sum()), N_in_rank1_4=int(g.N_in_rank1_4.sum()), cases_source=int(g.cases_source.sum()), beta=b, SE=se, estimate=math.exp(b), CI_lower=math.exp(b - Z * se), CI_upper=math.exp(b + Z * se), P=math.erfc(abs(b / se) / math.sqrt(2)), sex_heterogeneity_Q=Q, sex_heterogeneity_df=1, sex_heterogeneity_P=p_chi(Q, 1), assumption=\'Inverse-variance summary of disjoint sex strata, conditionally independent; working covariance\'))\n    alltrend = pd.concat([strata, pd.DataFrame(combined)], ignore_index=True)\n    save(alltrend, audit / \'SWEDEN_GLS_TRENDS_AND_SENSITIVITIES.csv\')\n    save(pd.DataFrame(matrices), audit / \'SWEDEN_WORKING_COVARIANCE_MATRICES.csv\')\n    save(pd.DataFrame(pseudo), audit / \'SWEDEN_WORKING_COUNTS.csv\')\n    save(counts, audit / \'SWEDEN_PUBLISHED_RANK_COUNTS.csv\')\n    save(hr, audit / \'SWEDEN_PUBLISHED_HRS.csv\')\n    save(pd.DataFrame(inp), audit / \'SOURCE_MANIFEST.csv\')\n    sw = alltrend[(alltrend.sex == \'Sex-combined\') & (alltrend.scenario == \'rank1_4\') & (alltrend.covariance_method == \'GL_cumulative_working\')].iloc[0]\n    uk = pd.read_csv(srcCox).iloc[0]\n    assert uk[\'rank_min\'] == 1 and uk[\'rank_max\'] == 4 and (uk.effect_type == \'HR\')\n    assert abs(uk.estimate - math.exp(uk.beta)) < 1e-12\n    old = pd.read_csv(srcDM, dtype={\'outcome\': str})\n    dm = old[(old.cohort == \'UKB\') & (old.outcome == \'250\')].iloc[0]\n    lasi = old[(old.cohort == \'LASI\') & (old.outcome == \'diabetes\')].iloc[0]\n    assert len(old[(old.cohort == \'UKB\') & (old.outcome == \'250\')]) == 1 and lasi.model == \'M1\'\n    final = [dict(panel=\'A\', cohort=\'UKB\', endpoint=\'IHD\', effect_type=\'HR\', estimate=uk.estimate, CI_lower=uk.CI_lower, CI_upper=uk.CI_upper, N=int(uk.N), events_or_cases=int(uk.events), exposure_unit=\'Per one absolute birth-rank increment; ranks1-4\', method_label=\'Pooled-sex Cox\', source_status=\'NEW_ONE_MODEL\', N_definition=\'Actual complete-case pooled Cox model N\'), dict(panel=\'A\', cohort=\'Sweden\', endpoint=\'CHD\', effect_type=\'HR\', estimate=sw.estimate, CI_lower=sw.CI_lower, CI_upper=sw.CI_upper, N=int(sw.N_source_model), events_or_cases=int(sw.cases_source), exposure_unit=\'Per one absolute birth-rank increment; ranks1-4\', method_label=\'GLST approximation\', source_status=\'USER_APPROVED_EXPLORATORY_WORKING_COVARIANCE\', N_definition=\'Full published source Cox cohorts; rank1-4 represented N=\' + str(int(sw.N_in_rank1_4))), *[dict(panel=\'B\', cohort=r.cohort, endpoint=\'DM\', effect_type=\'OR\', estimate=r.OR, CI_lower=r.CI_low, CI_upper=r.CI_high, N=int(r.N), events_or_cases=int(r.cases), exposure_unit=\'Relative birth position B:0 to1\', method_label=\'Frozen logistic\' if r.cohort == \'UKB\' else \'Frozen Firth logistic M1\', source_status=r.inference_status, N_definition=\'Saved model complete-case N\') for r in [dm, lasi]]]\n    final = pd.DataFrame(final)\n    assert len(final) == 4 and np.all(final.CI_lower < final.estimate) & np.all(final.estimate < final.CI_upper)\n    save(final, REPORT / \'FINAL_FOREST_VALUES.csv\')\n    text(audit / \'APPROXIMATION_AUTHORITY.json\', json.dumps(dict(user_approved=True, decision=\'采用近似趋势，图表及审计明确标注\', no_person_time_imputed=True, method=\'Orsini,Bellocco,Greenland2006 cumulative-incidence effective-count working correlation applied to published logHR\', not_claimed=\'Exact recovered Cox covariance, original published overall HR, or literal dosresmeta grl(ci) implementation\'), ensure_ascii=False, indent=2) + \'\\n\')\n    authority = json.loads((ROOT / \'RUN_AUTHORITY.json\').read_text())\n    ph = pd.read_csv(srcCox.parent / \'PH_DIAGNOSTICS.csv\')\n    pph = ph.set_index(\'term\')[\'p\']\n    mainstrata = strata[(strata.scenario == \'rank1_4\') & (strata.covariance_method == \'GL_cumulative_working\')]\n    sensitive = alltrend[alltrend.sex == \'Sex-combined\']\n    ds = []\n    for r in mainstrata.itertuples():\n        ds.append(f\'{r.sex}: approximate HR {r.estimate:.6f} ({r.CI_lower:.6f}–{r.CI_upper:.6f}); residual linear-fit Q={r.residual_Q:.4g}, df={int(r.residual_df)}, P={r.residual_P:.4g}.\')\n    sm = \'\\n\'.join((f\'- {r.scenario}; {r.covariance_method}: {r.estimate:.6f} ({r.CI_lower:.6f}–{r.CI_upper:.6f}).\' for r in sensitive.itertuples()))\n    text(REPORT / \'METHODS_EN.md\', f"# Methods and figure caption\\n\\n## Swedish summarized-data trend\\n\\nTable1 of Nilsson et al. provided sex-specific birth-rank population sizes and CHD case counts. Adjusted HRs and rounded95%CIs were taken from Tables2–3 without changing their values. Category-specific person-time and adjusted-Cox covariance were not reported. Therefore an exact incidence-rate/HR GLST reconstruction was not possible. At the user\'s explicit approval, we performed an exploratory generalized-least-squares trend analysis using a cumulative-incidence working covariance reconstruction, not a recovered Swedish Cox model.\\n\\nFollowing the cumulative-incidence equations in Orsini, Bellocco and Greenland(2006,p46), define R0=1, A0=sum(cases)/sum(Ri Ni/N0), Ai=A0 Ri Ni/N0. Original categoryN and total cases were preserved. We used s0=1/A0−1/N0, si=s0+1/Ai−1/Ni, rhoij=s0/sqrt(si sj), and Vij=SEi SEj rhoij, with diagonal SEi². Published log-HR SEs were [log(UCI)−log(LCI)]/(2×1.95996398454). HRs enter the working risk-ratio equations only to approximate correlation: HR is not generally a cumulative-risk ratio. This extra assumption, as well as preservation of crude-to-adjusted correlation, limits inference. We did not insertN as person-time or manufacture follow-up totals. This follows the published equations and is not claimed to be a literal clone of the current dosresmeta grl(ci) implementation.\\n\\nCovariance was reconstructed using all five original rank categories, including5+, to retain the published model margins. The primary linear component used only ranks2–4 versus rank1, x=(1,2,3), with no intercept: b=(x\'V^-1x)^-1x\'V^-1y and Var(b)=(x\'V^-1x)^-1. Thus the5+ category required no dose assignment for the primary trend. Male and female slopes were precision-weighted into one Swedish summary, conditionally treating the disjoint strata as independent. Their heterogeneity was recorded; the two sex strata were not presented as independent cohorts. CIs are conditional on the working covariance and do not include all reconstruction uncertainty.\\n\\nPredeclared sensitivities replaced the correlation with raw cumulative-incidence or raw Poisson case-count correlations and, separately, included5+ at assigned scores5 and6. These scores are scenario assumptions, not observed category means. Residual goodness-of-fit tests assess adequacy of the imposed linear component; a positive slope does not prove monotonicity. Swedish forestN is the full source-modelN=2,673,684; ranks1–4 represent2,587,786 participants. The source HRs were estimated using the full cohorts.\\n\\n## UKB and LASI\\n\\nOne additional pooled-sex UKB Cox model was fitted in frozen full-sibships S2–8, restricted to observed absolute ranks1–4. It retained the frozen IHD411 endpoint, complete follow-up, Efron ties, baseline age(linear), sex, official ethnicity groups, assessment center, assessment year, and categoricalS. Current withdrawals were excluded; no missing rank was filled. Actual N={int(uk.N):,}, events={int(uk.events):,}. Ordinary model-based covariance was used. Global and rank-specific proportional-hazards P values were {pph[\'GLOBAL\']:.4g} and {pph[\'border_rank\']:.4g}; these diagnostics are retained rather than resolved by an unrequested model change. The original relative-B analysis was not modified.\\n\\nPanelB directly reuses the saved UKB DM logistic estimate and LASI DM M1 Firth estimate, with no re-estimation. Both use relative birth position0→1, not a one-rank increment. LASI is diabetes mellitus, not a separately verified T2D endpoint. UKB uses ordinary logistic Wald inference; LASI uses unweighted Firth logistic with profile-likelihoodCI and its frozen age/sex/region/family-size/education/wealth adjustment. The saved UKB inference flag `{dm.inference_status}` is retained; this plotting task does not clear it.\\n\\nNo UKB–Sweden or UKB–LASI meta-analysis was performed. Swedish trend uncertainty is reconstructed approximately, reference populations and endpoint capture differ, and clinical ascertainment/adjustment differ. PanelA HRs and PanelB ORs also represent different exposure units and are not directly comparable or poolable across panels.\\n\\n## Figure caption\\n\\nQuantitative external comparisons of birth-order associations. PanelA shows a pooled-sex UKB Cox HR and a Swedish sex-combined GLST approximation per one absolute birth-rank increment across ranks1–4. The Swedish point is derived from published categorical HRs using a cumulative-incidence working covariance; it is not a directly reported overall Cox HR. PanelB shows saved diabetes-mellitus ORs for relative birth position0→1 in UKB and LASI. Points and bars denote estimates and95%CIs; N denotes source-model sample size. HR andOR panels have distinct units. These are observational quantitative comparisons, not causal validation or pooled cohort effects.\\n\\nReferences: Nilsson et al., BMJ Open2021;11:e042881, https://doi.org/10.1136/bmjopen-2020-042881 ; Greenland and Longnecker1992, https://doi.org/10.1093/oxfordjournals.aje.a116237 ; Orsini,Bellocco,Greenland2006, https://doi.org/10.1177/1536867X0600600103 ; Crippa and Orsini2016, https://www.jstatsoft.org/article/view/v072c01 ; Orsini2021, https://doi.org/10.1177/1536867X211025798 .\\n")\n    effectlines = \'\\n\'.join((f\'- {r.panel} / {r.cohort} / {r.endpoint}: {r.effect_type} {r.estimate:.6f}（{r.CI_lower:.6f}–{r.CI_upper:.6f}），N={r.N:,}；{r.exposure_unit}。\' for r in final.itertuples()))\n    text(REPORT / \'AUDIT_REPORT_ZH.md\', f"# 出生顺序外部定量对照：最终单图审计\\n\\n## 本轮最终结果\\n\\n{effectlines}\\n\\n仅交付一张双面板、四队列行的森林图。不再在图中列男女和各排行HR。之前男女分类分析的文件完整保留在原目录，没有覆盖。\\n\\n## 瑞典原文是否满足GLST条件？\\n\\nTable1确有男女×排行的人数及CHD事件数，已与补充表1a/1b交叉核对；Tables2–3有8项调整HR及CI。但没有排行分层人时或原Cox协方差。因此不满足无额外假设的标准发生率/HR-GLST精确重构条件。\\n\\n用户已明确选择“采用近似趋势，图表及审计明确标注”。本轮按Orsini等2006累计发生数据公式，采用工作协方差近似：用完整5组N、病例数和已发表HR重建有效计数及相关性，再用已发表SE设定协方差对角线。5+只参与协方差边际信息，主趋势不赋5+剂量；主趋势仅用2、3、4vs1。不是把HR当独立点简单回归，不是把人数当人时，也没有伪造任何病例或人时。其CI条件于近似协方差，不等于原研究个体级Cox趋势CI，图上明确写GLSTapproximation。\\n\\n分别计算男女线性分量后按逆方差汇成一个瑞典点，假定性别分层估计条件独立。男性/女性不是两个独立队列，没有把它们与UKB混作三项研究。源Cox队列N=2,673,684；其中排行1–4的N=2,587,786。图中N采用源模型人数，数值表另说明来源。\\n\\n{\' \'.join(ds)}\\n\\n性别趋势异质性Q={sw.sex_heterogeneity_Q:.4g}（df1，P={sw.sex_heterogeneity_P:.4g}）。残差Q和性别差异均是近似协方差下的诊断，不是原论文直接报告的检验；趋势为线性概要，不据此宣称发现严格单调剂量反应。\\n\\n男性的线性拟合残差检验P=0.00753，提示简单线性分量存在失拟。因此瑞典单点只能作为预先指定的线性概要，不应解释为其各排行之间恰好恒定的HR。UKB本轮HR的95%CI包含1（下限0.999772，P略大于0.05），正式图保留4位小数，避免将下限舍入为1.000造成显著性误读。\\n\\n## 预先说明的敏感性\\n\\n在读取趋势结果前固定：替换两种相关性模型，并将5+赋值5、6作情景检查。5、6不是原文平均排行。全部数值留在audit，不增加第二张主图。\\n\\n{sm}\\n\\n## UKB最小新增计算\\n\\n只新增1个不分男女的绝对排行趋势Cox：S2–8且实际排行1–4。年龄线性、性别、官方族裔、评估中心、评估年份、S分类，沿用冻结风险集、原完整随访及IHD411终点。N/事件数来自实际模型；全系数、样本流程、排行性别计数、协方差及PH诊断均保存。没有修改相对B主分析、没有填独生子女缺失排行。全模型PH P={pph[\'GLOBAL\']:.4g}；排行项PH P={pph[\'border_rank\']:.4g}。若全模型诊断不通过，应限制其正式解释，而非仅靠绘图把警示清除。\\n\\n## LASI及PanelB回收\\n\\nLASI完全复用已完成的DM M1结果，没有重新计算。其效应单位是相对出生位置B从0到1，不能转换成每增加一胎的OR。因此PanelB配对使用UKB既有DM结果，同为B0→1；不把LASI一般糖尿病冒称T2D。UKB原始状态`{dm.inference_status}`继续保留，本轮没有重新验收或清除既有Wald待复核标志。LASI原模型为不加权Firth、profileCI；不同方法与人群/疾病记录差异均在表中说明。\\n\\n## 是否Meta及外部支持力度\\n\\n本轮不做跨队列合并。瑞典趋势是获授权的近似重构；UKB与瑞典的独生子女参照、全/半同胞、致死/住院事件及协变量时点仍不同。DM两队列的端点来源、总体年龄及调整/拟合方式亦不同。四个点用于定量方向对照，不是同一种风险效应，不能把HR与OR或每胎与B0→1混合。没有生成合并菱形、合并HR或跨面板Meta。\\n\\n图形可用于补充性外部证据展示；需连同近似GLST说明及源结果状态使用，不应宣称完全同规格外部复制或因果确证。正的趋势摘要也不替代此前分类结果中出现的非单调情况。\\n\\n## 保留与复现\\n\\n远端新增唯一模型：`{authority[\'result_root\']}/private/model.rds`；个体数据没有回传。输入文件SHA、原文提取、近似矩阵、有效计数、性别中间趋势及敏感性均在audit。最终数值表只有4行。源数据、既有男女结果及所有其他计算队列未改动。\\n")\n    text(REPORT / \'REPRODUCE.md\', f"# Reproduce without rerunning LASI\\n\\nWorkstation root: `{PROJECT}`. Existing plotting environment: `.codex_tmp/border_figures_20261016_venv/bin/python`.\\n\\nCompleted UKB one-model run: `{authority[\'result_root\']}`. Do not repeat-launch the completed run. The source `fit_trend.R` accepts `EXTERNAL_TREND_INPUT`, `EXTERNAL_TREND_WITHDRAWALS`, `EXTERNAL_TREND_HELPER`, and an exclusive `EXTERNAL_TREND_OUTPUT`. It uses one thread, ordinary Cox covariance, and refuses changed frozen hashes. It was executed with nice19 and an8GiB virtual-memory limit.\\n\\nAggregate-only reproduction commands, in a new task/report version or before output files exist:\\n\\n```sh\\ncd {PROJECT}\\n.codex_tmp/border_figures_20261016_venv/bin/python -B scripts/birth/{ROOT.name}/build_trends.py\\n.codex_tmp/border_figures_20261016_venv/bin/python -B scripts/birth/{ROOT.name}/plot_external.py\\n```\\n\\nBoth scripts refuse overwrites. build_trends reads the exact Table1 extraction, the audited Swedish published-effect CSV from the preceding preserved report, the new saved UKB aggregate trend, and the existing UKB/LASI frozen forest source CSV. It never fits participant models. The original LASI inputs are not accessed and LASI is not recomputed. Working covariance uses all5categories; primary GLS uses the rank2/3/4 submatrix. No independence weighting of shared-reference contrasts is used.\\n\\nNo PheWAS,121/44mediation,bootstrap,relative-B refit or additional sex-specific Cox model was run for this revision. The4 earlier categorical models belong to the separately authorized previous design and remain preserved.\\n")\n    qc = dict(forest_rows=4, Sweden_user_approved_approximation=True, Sweden_actual_person_time_available=False, covariance_shared_reference=True, all_five_category_margins_retained=True, main_dose_ranks=[1, 2, 3, 4], covariance_sensitivities=methods, open_category_assigned_scores_sensitivity=[5, 6], UKB_additional_models=1, LASI_recomputed=False, cross_cohort_meta_performed=False, original_relative_B_modified=False)\n    text(REPORT / \'QC.json\', json.dumps(qc, indent=2) + \'\\n\')\n    print(final.to_string(index=False))\n    print(sensitive[[\'scenario\', \'covariance_method\', \'estimate\', \'CI_lower\', \'CI_upper\']].to_string(index=False))\nif __name__ == \'__main__\':\n    main()', '<private-stage>', 'exec'), context)
